                  name: {{ include "postgresql.secretName" . }}
                  key: postgres-username
            - name: PGPASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgresql.secretName" . }}
                  key: postgres-password
            - name: APP_DB
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgresql.secretName" . }}
                  key: postgres-database
          {{- with .Values.initJob.env }}
          envFrom:
            - configMapRef:
                name: {{ .configMapRef | default "" | quote }}
          {{- end }}
          resources:
            {{- toYaml .Values.initJob.resources | nindent 12 }}
          command:
            - /bin/sh
            - -c
            - |
              set -euo pipefail
              HOST="{{ include "postgresql.fullname" . }}-hl"
              PORT="{{ .Values.service.port }}"
